@Composable
private fun PrivacyScreen(onBack: () -> Unit) {
    DetailScaffold("Privacy", onBack) {
        item {
            GlassPanel {
                DetailPoint(Icons.Outlined.PhoneAndroid, "Stored on this phone", "Transactions, titles, notes, and settings remain in Penny’s local app storage.")
                SettingsDivider()
                DetailPoint(Icons.Outlined.Lock, "No bank login", "Penny never asks for your bank password, card PIN, or UPI PIN.")
                SettingsDivider()
                DetailPoint(Icons.Outlined.Sms, "Future alerts only", "SMS access captures new transaction alerts. Penny does not import your old inbox.")
            }
        }
        item {
            Text("Permissions", style = MaterialTheme.typography.titleLarge)
            Spacer(Modifier.height(10.dp))
            GlassPanel {
                Text("SMS", style = MaterialTheme.typography.titleMedium)
                Text("Used only to recognize new bank debit and credit alerts.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                SettingsDivider()
                Text("Notifications", style = MaterialTheme.typography.titleMedium)
                Text("Used to remind you to name a new expense.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
            }
